description:
Design a debounce circuit that filters out unwanted noise from a mechanical switch or similar input. The module monitors the input signal and utilizes a counter to ensure that the output remains stable for a specified debounce time (t) in milliseconds. When the input signal transitions, the counter resets, and if the signal remains stable beyond the debounce threshold, the output reflects the stable state of the input signal. This circuit effectively prevents false triggering caused by rapid on-off fluctuations, ensuring a clean and reliable output signal.
module top_module(
  input signal_in,
  output signal_out
);

code:
module top_module(
  input signal_in,
  output signal_out
);parameter t = 10; // debounce time in milliseconds

reg [31:0] counter;
reg signal_out_reg;
wire signal_in_sync;

assign signal_in_sync = signal_in;

always @(posedge signal_in_sync) begin
  counter <= 0;
end

always @(posedge signal_in_sync) begin
  if (counter < t) begin
    counter <= counter + 1;
    signal_out_reg <= signal_out_reg;
  end else begin
    counter <= 0;
    signal_out_reg <= signal_in_sync;
  end
end

assign signal_out = signal_out_reg;

endmodule

