module shift_register (clk, reset, load, shift_left, shift_right, parallel_in, q);
   input clk;
   input reset;
   input load;
   input shift_left;
   input shift_right;
   input [3:0] parallel_in;
   output [3:0] q;

   reg [3:0] q;

