    if (reset)
        q <= 4'b0000;
    else if (load)
        q <= parallel_in;
    else if (shift_left)
        q <= {q[2:0], 1'b0};
    else if (shift_right)
        q <= {1'b0, q[3:1]};
end

endmodule

