        sram_oe_n <= 1'b1;
    end else begin
        sram_ce_n <= 1'b0;
        sram_oe_n <= 1'b0;
    end
end

// Read data from SRAM
always @ (posedge clk) begin
    if (reset) begin
        data_out <= 16'b0;
    end else begin
        if (!write_enable) begin
            data_out <= sram_data;
        end
    end
end

// Write data to SRAM
always @ (posedge clk) begin
    if (reset) begin
        sram_data <= 16'b0;
    end else begin
        if (write_enable) begin
            sram_data <= data_in;
        end
    end
end

