description:
Design a dual-edge-triggered D flip-flop circuit that operates on a clock input (C) with a reset input (R). This module captures the input data (D) on both the positive edge (for Q1) and the negative edge (for Q2) of the clock, and it resets both outputs (Q1 and Q2) to LOW when the reset signal (R) is asserted. The outputs represent the stored values from the corresponding clock edges.
module top_module(
   output Q1, Q2,
   input  C,CE,D,R,S
);

code:
module top_module(
   output Q1, Q2,
   input  C,CE,D,R,S
);reg [1:0] Qi;

   always@(posedge C or posedge R) begin
      if (R) begin
         Qi[0] <= 1'b0;
      end
      else begin
         Qi[0] <= D;
      end
   end

   always@(negedge C or posedge R) begin
      if (R) begin
         Qi[1] <= 1'b0;
      end
      else begin
         Qi[1] <= D;
      end
   end

   assign Q1 = Qi[0];
   assign Q2 = Qi[1];

endmodule

